async function detailFor(d){const descriptor=d?.detail;if(!descriptor)return null;const key=idOf(d);if(state.details.has(key))return state.details.get(key);if(!state.detailPromises.has(key))state.detailPromises.set(key,json(descriptor.file,descriptor).then(x=>{state.details.set(key,x);return x;}).finally(()=>state.detailPromises.delete(key)));return state.detailPromises.get(key);}
