    const d=A().matrices?.[metric],ids=arr(A().matrices?.source_ids);if(!d?.file||!ids.length)throw new Error('No reviewed matrix is supplied for this representation.');if(d.dtype!=='float32-le'||d.shape?.[0]!==ids.length||d.shape?.[1]!==ids.length)throw new Error('Unsupported matrix encoding or shape.');
